TOPICS = build_guided_catalog([
    ("css-intro", "What CSS Is and Why It Matters", "foundations", "basic", "CSS (Cascading Style Sheets) controls how HTML content looks and lays out across screen sizes. It separates presentation rules from document content.", "h1 { color: rebeccapurple; }", "What does CSS add to HTML?", "It describes visual presentation and layout so content can be styled consistently across a site."),
    ("css-selectors", "Selectors, Specificity and Scope", "foundations", "basic", "Selectors choose elements for a rule. Specificity and source order help determine which competing declaration wins; small scoped selectors are easier to maintain.", ".card > h2 { margin-block: 0; }", "What should you check when a CSS rule does not apply?", "Confirm the selector matches, the stylesheet loads, and no stronger declaration or invalid value overrides it."),
    ("css-cascade", "The Cascade, Inheritance and Layers", "foundations", "intermediate", "The cascade resolves declarations using origin, importance, layers, specificity and source order. Inherited properties flow from ancestors unless overridden.", "@layer reset, components, utilities;", "Why can an earlier rule win over a later one?", "Cascade origin, importance, layer order or specificity can take priority over source order."),
    ("css-box-model", "The Box Model and box-sizing", "foundations", "basic", "An element's box includes content, padding, border and margin. Border-box sizing makes declared dimensions include padding and border.", "*, *::before, *::after { box-sizing: border-box; }", "What does border-box change?", "The declared width and height include the content, padding and border."),
    ("css-colors", "Color, Contrast and Design Tokens", "foundations", "basic", "Color can be expressed in hex, RGB, HSL or modern color functions. Tokens make shared colors consistent; text and controls still need sufficient contrast.", ":root { --accent: #6842d8; color: var(--accent); }", "Why use CSS custom properties?", "They provide reusable design values that can be changed centrally and themed by scope."),
    ("css-typography", "Typography and Readability", "foundations", "basic", "Typography rules control font choice, size, line-height, measure, spacing and wrapping. Readability depends on combinations, not font size alone.", "body { font: 1rem/1.6 system-ui, sans-serif; }", "Why set line-height?", "It controls the space between lines and strongly affects reading comfort and content density."),
    ("css-units", "CSS Units and Fluid Sizing", "foundations", "basic", "CSS units express fixed, relative or viewport-based sizes. Relative units such as rem and percentages support scaling with user and container context.", "font-size: clamp(1.5rem, 4vw, 3rem);", "When is rem useful?", "For sizes that should scale relative to the root font size, such as spacing and text."),
    ("css-flexbox", "Flexbox for One-Dimensional Layout", "layout", "basic", "Flexbox distributes items along one main axis and aligns them on the cross axis. It is useful for toolbars, navigation and rows of content.", ".row { display: flex; align-items: center; gap: 1rem; }", "When is Flexbox a good fit?", "When items need to flow and align along a single primary row or column."),
    ("css-grid", "Grid for Two-Dimensional Layout", "layout", "basic", "CSS Grid defines rows and columns together, making it useful for page layouts, cards and regions that align in two dimensions.", ".cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr)); }", "What can Grid express more directly than Flexbox?", "A coordinated two-dimensional track system with explicit rows and columns."),
    ("css-position", "Positioning, Stacking Contexts and z-index", "layout", "intermediate", "Positioning removes or offsets elements from normal flow. z-index only compares within stacking-context rules, so transforms and opacity can change which elements stack together.", ".toast { position: fixed; inset: auto 1rem 1rem auto; }", "Why might a high z-index still appear behind another element?", "The element may be inside a lower stacking context that cannot outrank its sibling context."),
    ("css-responsive", "Responsive Layout and Media Queries", "layout", "basic", "Responsive CSS adapts layout to available space and user preferences. Start from content constraints and add breakpoints when the design needs them.", "@media (max-width: 40rem) { .layout { grid-template-columns: 1fr; } }", "How should a breakpoint be chosen?", "Choose it where the content or layout stops working well, rather than targeting one device model."),
    ("css-container", "Container Queries", "layout", "intermediate", "Container queries style a component based on the size of its containing region rather than the full viewport. This helps reusable components adapt inside different layouts.", ".panel { container-type: inline-size; } @container (width > 35rem) { ... }", "What question does a container query answer?", "How should this component change based on the space its container gives it?"),
    ("css-custom-props", "CSS Custom Properties and Themes", "visual", "intermediate", "Custom properties inherit through the cascade and can be updated by themes or component scope. Use semantic token names for intent rather than raw color values everywhere.", "--surface-raised: color-mix(in srgb, white 8%, var(--surface));", "Why name a token by purpose?", "A semantic name lets the underlying value change without rewriting every component that uses it."),
    ("css-gradients", "Gradients, Backgrounds and Layers", "visual", "basic", "A background can combine color, gradients and images in layers. Ordering determines which layer appears on top; test text contrast over the full area.", "background: linear-gradient(135deg, #6d5dfc, #35c9be);", "Which background layer is painted on top?", "The first listed background image or gradient is painted on top of later layers."),
    ("css-shadow", "Shadows, Depth and Elevation", "visual", "basic", "Shadows can suggest separation and depth, but heavy or repeated shadows reduce clarity and can affect perceived contrast. Use a small, consistent scale.", "box-shadow: 0 12px 28px -18px rgb(0 0 0 / .45);", "What makes a shadow feel subtle?", "Low opacity, controlled blur and distance, and consistent use with the rest of the interface."),
    ("css-glassmorphism", "Glassmorphism and Backdrop Filters", "visual", "intermediate", "Glassmorphism combines translucent surfaces, background blur and a light border. Keep foreground contrast readable and provide a solid fallback when backdrop filters are unavailable.", "background: rgb(255 255 255 / .14); backdrop-filter: blur(16px);", "What accessibility risk does translucent glass introduce?", "Background content can reduce text contrast, so ensure the surface remains readable over varied backgrounds."),
    ("css-neumorphism", "Neumorphism and Soft UI", "visual", "intermediate", "Neumorphism uses light and dark shadows on a similar surface color to suggest a raised or pressed control. Its low contrast can make boundaries and states hard to perceive.", "box-shadow: 8px 8px 18px #c2c5cb, -8px -8px 18px #fff;", "What should be added to a soft neumorphic control?", "Clear labels, visible focus, a distinguishable pressed state and sufficient contrast."),
    ("css-claymorphism", "Claymorphism and Rounded Surfaces", "visual", "intermediate", "Claymorphism uses rounded shapes, layered shadows and bright surfaces to create a soft dimensional look. Keep the effect restrained so content and controls remain clear.", "border-radius: 24px; box-shadow: 10px 10px 22px #c7c9d0, -8px -8px 18px #fff;", "How can a claymorphic surface remain usable?", "Use strong text contrast and clear borders or focus states; decoration should not obscure interaction."),
    ("css-motion", "Transitions, Motion and Reduced Motion", "quality", "intermediate", "Transitions and keyframes communicate state changes. Respect prefers-reduced-motion and avoid animation that delays essential content or triggers discomfort.", "@media (prefers-reduced-motion: reduce) { * { animation-duration: .01ms; } }", "How should a page respect reduced-motion settings?", "Reduce or remove nonessential movement when the user requests reduced motion."),
    ("css-accessibility", "Focus, Contrast and Accessible States", "quality", "basic", "Interactive controls need visible keyboard focus, sufficient contrast and clear states beyond color alone. Use semantic HTML and test at zoom and with keyboard navigation.", ":focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }", "Why not remove the browser outline without replacement?", "Keyboard users need a visible indication of which control currently has focus."),
    ("css-performance", "CSS Performance and Rendering Cost", "quality", "advanced", "Prefer straightforward selectors and avoid expensive full-screen effects on many elements. Large blurs, filters and continuously animated properties can consume GPU and battery.", "Animate transform and opacity for small transitions; avoid animating layout dimensions", "Why can large backdrop filters be costly?", "They may require large areas of pixels to be repainted or composited, especially during motion."),
], "CSS", ANALOGY)
